/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: subject, credit, entry, reviewDoc
 *   Constants: reviewId, slotA, slotB, revision
 * Tests
 *   - review naming evidence accepts only actual bounded basenames and preserves missing evidence
 *   - apply selection cannot mutate Artist identity, Credits, label, visibility, files or another scope
 *   - catalog analysis cannot claim nonexistent folder or missing filename evidence
 *   - apply selection holds at most the two Album fields and three per Track
 *   - review context keeps stored Credit order, primary and featured Artists only, each name once, adjacent join phrases and the first named label
 *   - only a draft with an own Album artistName is a v1 review draft
 *   - a review save keeps the stored Credits context, label, visibility and uncaptured Disc Numbers and parses only titles, date and numbers
 *   - a v1 review converts to Draft v2 with the legacy entry, its baseline and suggestions, and no value origins; anything else is unchanged
 * @end-catalog */

import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { test } from 'node:test';
import { ObjectId } from 'mongodb';
import { catalogReviewCredits, catalogReviewOriginalFilename, convertLegacyCatalogReview, isLegacyCatalogReviewDraft, parseCatalogReviewDraft, parseCatalogReviewFields } from '../../src/administration/catalog/adminCatalogReviewService';
import { validateAnalysisSuggestions, type AnalysisInput } from '../../src/administration/import/adminImportProvider';
import { uuid } from '../../src/administration/import/adminImportContract';
import { legacyArtistEntryKey } from '../../src/administration/import/adminImportDraftCompat';
import type { ImportArtistEntry, ImportDraftV2 } from '../../src/administration/import/adminImportDraft';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import type { CatalogCredit } from '../../src/models/catalogCredit';

// Every identity and name below is synthetic.
const reviewId = '0000000000000000000000e1', slotA = '00000009-0000-4000-a000-0000000000e1', slotB = '00000009-0000-4000-a000-0000000000e2', revision = `cr_${'e'.repeat(43)}`;
const subject = (n: number) => n.toString(16).padStart(24, '0');
const credit = (creditId: string, subjectType: CatalogCredit['subjectType'], n: number, role: CatalogCredit['role'], order: number, joinPhrase?: string): CatalogCredit =>
    ({ creditId, subjectType, subjectId: subject(n), role, order, ...(joinPhrase === undefined ? {} : { joinPhrase }) });
const entry = (key: string, name: string, role: ImportArtistEntry['role'], joinPhrase: string | null): ImportArtistEntry => ({ key, name, role, joinPhrase, musicBrainzId: null });
/** An in-memory Draft v2 review with Credits context, a label and one captured and one uncaptured source disc. */
function reviewDoc(): { doc: AdminImportDocument; stored: ImportDraftV2 } {
    const stored: ImportDraftV2 = {
        album: { title: 'Synthetic Album', artists: [entry('00000009-0000-4000-8000-0000000000e1', 'Synthetic A', 'primary', ' & '), entry('00000009-0000-4000-8000-0000000000e2', 'Synthetic B', 'featured', null)],
            label: { name: 'Synthetic Label', musicBrainzId: null }, releaseDate: { year: 2020, month: null, day: null }, visibility: 'hidden' },
        tracks: [{ slotId: slotA, title: 'One', discNumber: 1, trackNumber: 1 }, { slotId: slotB, title: 'Two', discNumber: null, trackNumber: null }]
    };
    const doc = { _id: new ObjectId(reviewId), purpose: 'catalogReview', draftVersion: 2, actorId: subject(1), revision: 3, createdAt: new Date(0), updatedAt: new Date(0),
        manifest: { rootLabel: '', files: [slotA, slotB].map(slotId => ({ slotId, filename: '', relativePath: '', byteLength: null })) },
        catalogSource: { album: { id: subject(2), revision, title: 'Synthetic Album', releaseDate: { year: 2020, month: null, day: null }, visibility: 'hidden' },
            tracks: [{ slotId: slotA, id: subject(3), revision, title: 'One', discNumber: 1, trackNumber: 1, originalFileName: null }, { slotId: slotB, id: subject(4), revision, title: 'Two', trackNumber: null, originalFileName: null }] },
        draft: structuredClone(stored), analysis: { state: 'idle', generation: 0, operationId: null, actorId: null, grantExpiresAt: null, baseline: null, chunks: [], issue: null, leaseOwner: null, leaseUntil: null },
        analysisHistory: [], attemptsUsed: 0, suggestions: [], decisions: [], receipts: [] } as unknown as AdminImportDocument;
    return { doc, stored: doc.draft as ImportDraftV2 };
}

test('review naming evidence accepts only actual bounded basenames and preserves missing evidence', () => {
    for (const input of [undefined, null, '', '/private/music/song.mp3', 'C:\\music\\song.mp3', '../song.mp3', '\ud800', 'Song\u0000.mp3', 'x'.repeat(256)]) assert.equal(catalogReviewOriginalFilename(input), null);
    assert.equal(catalogReviewOriginalFilename(' 01 标题.mp3 '), '01 标题.mp3');
});
test('apply selection cannot mutate Artist identity, Credits, label, visibility, files or another scope', () => {
    const slotId = randomUUID();
    assert.deepEqual(parseCatalogReviewFields([{ scope: 'track', slotId, field: 'trackNumber' }]), [{ scope: 'track', slotId, field: 'trackNumber' }]);
    assert.deepEqual(parseCatalogReviewFields([{ scope: 'track', slotId, field: 'discNumber' }]), [{ scope: 'track', slotId, field: 'discNumber' }]);
    for (const field of ['artistName', 'artists', 'label', 'discNumber', 'credits', 'visibility', 's3Key', 'albumId']) assert.throws(() => parseCatalogReviewFields([{ scope: 'album', slotId: null, field }]), field);
    for (const field of ['artists', 'label', 'releaseDate', 'visibility']) assert.throws(() => parseCatalogReviewFields([{ scope: 'track', slotId, field }]), field);
    for (const input of [[], [{ scope: 'artist', slotId: null, field: 'title' }], [{ scope: 'track', slotId, field: 'releaseDate' }], [{ scope: 'album', slotId, field: 'title' }], [{ scope: 'album', slotId: null, field: 'title', value: 'Not saved' }]]) assert.throws(() => parseCatalogReviewFields(input));
    const repeated = { scope: 'album', slotId: null, field: 'title' }; assert.throws(() => parseCatalogReviewFields([repeated, repeated]));
});
test('catalog analysis cannot claim nonexistent folder or missing filename evidence', () => {
    const slotId = randomUUID();
    const input: AnalysisInput = { purpose: 'catalogReview', generation: 1, chunk: 0, album: true, slots: [], manifest: { rootLabel: '', files: [{ slotId, filename: '', relativePath: '', byteLength: null }] }, baseline: { album: { title: 'Existing title', artistName: '', releaseDate: null, visibility: 'public' }, tracks: [] } };
    const suggestion = { scope: 'album', slotId: null, field: 'title', text: 'Correction', number: null, date: null, source: 'context', evidence: 'Existing title context' };
    assert.equal(validateAnalysisSuggestions({ suggestions: [suggestion] }, input)[0].source, 'context');
    for (const source of ['filename', 'folder']) assert.throws(() => validateAnalysisSuggestions({ suggestions: [{ ...suggestion, source }] }, input));
    input.manifest.files[0].filename = '01 - Real.mp3';
    assert.equal(validateAnalysisSuggestions({ suggestions: [{ ...suggestion, source: 'filename' }] }, input)[0].source, 'filename');
    const trackInput: AnalysisInput = { ...input, album: false, slots: [slotId], baseline: { ...input.baseline, tracks: [{ slotId, title: 'Existing', trackNumber: null }] } };
    const trackNumber = { ...suggestion, scope: 'track', slotId, field: 'trackNumber', text: null, number: 3 };
    assert.throws(() => validateAnalysisSuggestions({ suggestions: [trackNumber] }, trackInput));
    assert.equal(validateAnalysisSuggestions({ suggestions: [{ ...trackNumber, source: 'filename' }] }, trackInput)[0].value, 3);
    trackInput.manifest.files[0].filename = '';
    assert.throws(() => validateAnalysisSuggestions({ suggestions: [{ ...trackNumber, source: 'filename' }] }, trackInput));
});
test('apply selection holds at most the two Album fields and three per Track', () => {
    const tracks = (count: number) => Array.from({ length: count }, () => randomUUID()).flatMap(slotId => ['title', 'discNumber', 'trackNumber'].map(field => ({ scope: 'track', slotId, field })));
    const album = [{ scope: 'album', slotId: null, field: 'title' }, { scope: 'album', slotId: null, field: 'releaseDate' }];
    assert.equal(parseCatalogReviewFields([...album, ...tracks(100)]).length, 302);
    assert.throws(() => parseCatalogReviewFields([...album, ...tracks(100), { scope: 'track', slotId: randomUUID(), field: 'title' }]));
});

test('review context keeps stored Credit order, primary and featured Artists only, each name once, adjacent join phrases and the first named label', () => {
    const names = new Map([[subject(10), ' Synthetic A '], [subject(11), 'Synthetic B'], [subject(12), 'Synthetic C'], [subject(13), 'Synthetic Performer'], [subject(14), 'Synthetic D'],
        [subject(16), '   '], [subject(17), 'Synthetic Legacy'], [subject(18), 'Synthetic F'], [subject(19), 'Synthetic A']]);
    const organizations = new Map([[subject(31), 'Synthetic Label'], [subject(32), 'Second Synthetic Label'], [subject(33), 'Synthetic Publisher'], [subject(10), 'Not an Artist']]);
    const credits = [
        credit('c1', 'artist', 10, 'primary', 0, ' & '), credit('c2', 'artist', 11, 'featured', 1, ' feat. '), credit('c3', 'artist', 12, 'primary', 2, ' with '),
        credit('c4', 'artist', 13, 'performer', 3, ' x '), credit('c5', 'artist', 14, 'featured', 4, ' and '), credit('c6', 'artist', 15, 'primary', 5, ' / '),
        credit('c7', 'artist', 16, 'primary', 6, ' + '), credit('c8', 'artist', 17, 'legacyUnspecified', 7), credit('o1', 'organization', 30, 'label', 8),
        credit('o2', 'organization', 31, 'label', 9), credit('o3', 'organization', 32, 'label', 10), credit('o4', 'organization', 33, 'publisher', 11),
        credit('c9', 'artist', 18, 'primary', 12, ' , '), credit('c10', 'artist', 19, 'featured', 13, ' end ')
    ];
    const context = catalogReviewCredits(reviewId, credits, names, organizations);
    // A featured Artist stays where it is stored; a performer, an unresolved or empty name, a Credit outside the entry roles and a
    // repeated name are skipped and break adjacency, so the phrase before them is cleared; the last entry joins nothing.
    assert.deepEqual(context.artists.map(({ name, role, joinPhrase }) => [name, role, joinPhrase]), [
        ['Synthetic A', 'primary', ' & '], ['Synthetic B', 'featured', ' feat. '], ['Synthetic C', 'primary', null], ['Synthetic D', 'featured', null],
        ['Synthetic F', 'primary', null]
    ]);
    // One Artist credited as primary and featured is shown once, at its first Credit, as the catalog byline shows it.
    const twice = [credit('t1', 'artist', 11, 'primary', 0, ' & '), credit('t2', 'artist', 11, 'featured', 1, ' with '), credit('t3', 'artist', 12, 'featured', 2)];
    assert.deepEqual(catalogReviewCredits(reviewId, twice, names, organizations).artists.map(({ name, role, joinPhrase }) => [name, role, joinPhrase]),
        [['Synthetic B', 'primary', null], ['Synthetic C', 'featured', null]]);
    assert.deepEqual(context.label, { name: 'Synthetic Label', musicBrainzId: null });
    assert.equal(context.artists.every(value => uuid(value.key) && value.musicBrainzId === null), true);
    assert.equal(new Set(context.artists.map(value => value.key)).size, context.artists.length);
    assert.deepEqual(catalogReviewCredits(reviewId, credits, names, organizations), context, 'deterministic');
    assert.notDeepEqual(catalogReviewCredits('0000000000000000000000e2', credits, names, organizations).artists.map(value => value.key), context.artists.map(value => value.key));
    assert.deepEqual(catalogReviewCredits(reviewId, null, names, organizations), { artists: [], label: null });
    assert.deepEqual(catalogReviewCredits(reviewId, credits.filter(value => value.role !== 'label'), names, organizations).label, null);
    // At most 20 entries; the twentieth then joins nothing, because the next stored Credit is not shown.
    const many = Array.from({ length: 21 }, (_, index) => credit(`m${index}`, 'artist', 100 + index, 'primary', index, ' & '));
    const capped = catalogReviewCredits(reviewId, many, new Map(many.map((value, index) => [value.subjectId, `Synthetic ${index}`])), new Map()).artists;
    assert.equal(capped.length, 20); assert.deepEqual(capped.map(value => value.joinPhrase), [...Array.from({ length: 19 }, () => ' & '), null]);
    assert.equal(capped[19].name, 'Synthetic 19');
});

test('only a draft with an own Album artistName is a v1 review draft', () => {
    assert.equal(isLegacyCatalogReviewDraft({ album: { title: '', artistName: '', releaseDate: null, visibility: 'public' }, tracks: [] }), true);
    for (const value of [reviewDoc().stored, { album: Object.create({ artistName: 'x' }) }, { album: [] }, { album: null }, { album: 'artistName' }, null, 'x', [], undefined]) assert.equal(isLegacyCatalogReviewDraft(value), false, JSON.stringify(value));
});

test('a review save keeps the stored Credits context, label, visibility and uncaptured Disc Numbers and parses only titles, date and numbers', () => {
    const { doc, stored } = reviewDoc(), body = () => structuredClone(stored);
    assert.deepEqual(parseCatalogReviewDraft(body(), doc, stored), stored);
    // Tracks come back in manifest order, edited values parsed (NFC), and the stored context is kept as stored.
    const edited = body(); edited.tracks.reverse(); edited.album.title = ' Cafe\u0301 '; edited.tracks[0].title = 'Edited two'; edited.tracks[1].title = 'Edited one'; edited.tracks[1].trackNumber = 9999; edited.tracks[1].discNumber = 999;
    const parsed = parseCatalogReviewDraft(edited, doc, stored);
    assert.deepEqual(parsed.tracks, [{ slotId: slotA, title: 'Edited one', discNumber: 999, trackNumber: 9999 }, { slotId: slotB, title: 'Edited two', discNumber: null, trackNumber: null }]);
    assert.equal(parsed.album.title, 'Caf\u00e9'); assert.equal(parsed.album.artists, stored.album.artists); assert.equal(parsed.album.label, stored.album.label);
    // Entry key order is irrelevant; only the values compare.
    const reordered = body(); reordered.album.artists = reordered.album.artists.map(({ musicBrainzId, joinPhrase, role, name, key }) => ({ musicBrainzId, joinPhrase, role, name, key }));
    assert.deepEqual(parseCatalogReviewDraft(reordered, doc, stored), stored);
    const refused: [string, (draft: any) => void][] = [
        ['rename', draft => { draft.album.artists[0].name = 'Renamed'; }], ['reorder', draft => { draft.album.artists.reverse(); }],
        ['role', draft => { draft.album.artists[1].role = 'primary'; }], ['phrase', draft => { draft.album.artists[0].joinPhrase = ' and '; }],
        ['clear phrase', draft => { draft.album.artists[0].joinPhrase = null; }], ['remove entry', draft => { draft.album.artists.pop(); }],
        ['add entry', draft => { draft.album.artists.push(entry(randomUUID(), 'Synthetic New', 'featured', null)); }],
        ['entry key', draft => { draft.album.artists[0].key = randomUUID(); }], ['entry MusicBrainz ID', draft => { draft.album.artists[0].musicBrainzId = '00000009-0000-4000-9000-0000000000e1'; }],
        ['entry extra key', draft => { draft.album.artists[0].extra = true; }], ['label removed', draft => { draft.album.label = null; }],
        ['label renamed', draft => { draft.album.label.name = 'Renamed Label'; }], ['visibility', draft => { draft.album.visibility = 'public'; }],
        ['missing label', draft => { delete draft.album.label; }], ['missing artists', draft => { delete draft.album.artists; }], ['missing disc', draft => { delete draft.tracks[0].discNumber; }],
        ['extra album key', draft => { draft.album.artistName = 'Synthetic A'; }], ['extra top-level key', draft => { draft.extra = 1; }], ['extra track key', draft => { draft.tracks[0].extra = 1; }],
        ['track count', draft => { draft.tracks.pop(); }], ['unknown slot', draft => { draft.tracks[1].slotId = randomUUID(); }], ['duplicate slot', draft => { draft.tracks[1].slotId = slotA; }],
        ['uncaptured disc set', draft => { draft.tracks[1].discNumber = 2; }], ['disc 0', draft => { draft.tracks[0].discNumber = 0; }], ['disc 1000', draft => { draft.tracks[0].discNumber = 1000; }], ['disc 1.5', draft => { draft.tracks[0].discNumber = 1.5; }],
        ['track 0', draft => { draft.tracks[0].trackNumber = 0; }], ['Album title 301', draft => { draft.album.title = 'x'.repeat(301); }], ['track title 301', draft => { draft.tracks[0].title = 'x'.repeat(301); }],
        ['control character', draft => { draft.tracks[0].title = 'Bad\u0007'; }], ['release month 13', draft => { draft.album.releaseDate = { year: 2020, month: 13, day: null }; }],
        ['not an object', draft => { draft.album = []; }]
    ];
    for (const [label, change] of refused) { const draft = body(); change(draft); assert.throws(() => parseCatalogReviewDraft(draft, doc, stored), { code: 'ADMIN_IMPORT_INVALID_INPUT' }, label); }
    // A review without a label refuses adding one.
    const unlabelled = { ...stored, album: { ...stored.album, label: null } };
    assert.throws(() => parseCatalogReviewDraft({ ...unlabelled, album: { ...unlabelled.album, label: { name: 'Synthetic Label', musicBrainzId: null } } }, doc, unlabelled), { code: 'ADMIN_IMPORT_INVALID_INPUT' });
    assert.deepEqual(parseCatalogReviewDraft(structuredClone(unlabelled), doc, unlabelled), unlabelled);
    // An uncaptured track keeps whatever Disc Number the review already shows: it can be saved again, never changed or cleared.
    const hidden = { ...stored, tracks: stored.tracks.map(track => track.slotId === slotB ? { ...track, discNumber: 3 } : track) };
    assert.deepEqual(parseCatalogReviewDraft(structuredClone(hidden), doc, hidden), hidden);
    const cleared = structuredClone(hidden); cleared.tracks[1].discNumber = null;
    assert.throws(() => parseCatalogReviewDraft(cleared, doc, hidden), { code: 'ADMIN_IMPORT_INVALID_INPUT' });
});

test('a v1 review converts to Draft v2 with the legacy entry, its baseline and suggestions, and no value origins; anything else is unchanged', () => {
    const { doc: base } = reviewDoc(), id = base._id.toHexString();
    const v1Draft = { album: { title: 'Synthetic Album', artistName: ' Synthetic Artist ', releaseDate: { year: 2020, month: null, day: null }, visibility: 'hidden' },
        tracks: [{ slotId: slotA, title: 'One', trackNumber: 1 }, { slotId: slotB, title: 'Two', trackNumber: null }] };
    const source = { ...base.catalogSource!, tracks: base.catalogSource!.tracks.map(({ discNumber: _disc, ...track }) => track) };
    const suggestion = { scope: 'album', slotId: null, source: 'context', evidence: 'Synthetic evidence', generation: 1, decision: 'pending' }, receipt = { operationId: randomUUID(), kind: 'create', revision: 1, actorId: subject(1), hash: 'f'.repeat(64), at: new Date(0) };
    // A review stored before this release: no draftVersion, a v1 draft and baseline, a v1 Artist suggestion and no captured discs.
    const legacyDoc = (analysis: object = { ...base.analysis, state: 'complete', generation: 1, baseline: structuredClone(v1Draft) }) => {
        const { draftVersion: _version, ...rest } = reviewDoc().doc;
        return { ...rest, catalogSource: structuredClone(source), draft: structuredClone(v1Draft), analysis, receipts: [structuredClone(receipt)],
            suggestions: [{ ...suggestion, id: 'a'.repeat(24), field: 'artistName', baseline: ' Synthetic Artist ', value: 'Synthetic Corrected' }, { ...suggestion, id: 'b'.repeat(24), field: 'title', baseline: 'Synthetic Album', value: 'Synthetic Title' }] } as unknown as AdminImportDocument;
    };
    const legacy = legacyDoc(), before = legacyDoc(); convertLegacyCatalogReview(legacy);
    const key = legacyArtistEntryKey(id), artist = [entry(key, 'Synthetic Artist', 'primary', null)];
    const expected = { album: { title: 'Synthetic Album', artists: artist, label: null, releaseDate: { year: 2020, month: null, day: null }, visibility: 'hidden' },
        tracks: [{ slotId: slotA, title: 'One', discNumber: null, trackNumber: 1 }, { slotId: slotB, title: 'Two', discNumber: null, trackNumber: null }] };
    assert.equal(legacy.draftVersion, 2); assert.deepEqual(legacy.draft, expected); assert.deepEqual(legacy.analysis.baseline, expected);
    assert.deepEqual(legacy.suggestions.map(value => [value.field, value.baseline, value.value]), [['artists', artist, [entry(key, 'Synthetic Corrected', 'primary', null)]], ['title', 'Synthetic Album', 'Synthetic Title']]);
    assert.equal('draftOrigins' in legacy, false);
    assert.deepEqual([legacy.catalogSource, legacy.decisions, legacy.receipts, legacy.manifest, legacy.revision], [before.catalogSource, before.decisions, before.receipts, before.manifest, before.revision]);
    const converted = JSON.stringify(legacy); convertLegacyCatalogReview(legacy); assert.equal(JSON.stringify(legacy), converted, 'idempotent');
    // An idle v1 review has no baseline to convert.
    const idle = legacyDoc(structuredClone(base.analysis)); convertLegacyCatalogReview(idle); assert.deepEqual([idle.draftVersion, idle.analysis.baseline], [2, null]);
    for (const doc of [reviewDoc().doc, { ...reviewDoc().doc, draftVersion: 3 }, { ...legacyDoc(), purpose: 'import' }, { ...legacyDoc(), purpose: null }]) {
        const copy = JSON.stringify(doc); convertLegacyCatalogReview(doc as AdminImportDocument); assert.equal(JSON.stringify(doc), copy);
    }
});
